// Google solo da marcadores relativos: 'hace 5 dias' significaria otra cosa manana.
// Los traducimos con la misma regla que Dia a dia, anclada a la fecha de captura.
function fechaDeResena(relativa){
  const v=String(relativa).toLowerCase().replace(/ /g,' ');
  const dias=v.match(/(\d+)\s*d[ií]a/);
  let label=null;
  if(v.includes('4 semana')) label='4 semanas';
  else if(v.includes('3 semana')) label='3 semanas';
  else if(v.includes('2 semana')) label='2 semanas';
  else if(v.includes('una semana')||v.includes('1 semana')) label='1 semana';
  else if(v.includes('minuto')||v.includes('hora')) label='hoy';
  else if(v.includes('un día')||v.includes('un dia')) label='-1d';
  else if(dias && +dias[1]>=2 && +dias[1]<=6) label='-'+dias[1]+'d';
  return label && dayTimelineLabels[label] ? dayTimelineLabels[label].full : relativa;
}
function dec2(value){ return value.toFixed(2).replace('.', ','); }
function pLabel(value) { return value === null ? 'n/d' : value.toFixed(3).replace('.', ','); }
function sparkline(metric) {
  const width = 150, height = 42, pad = 5, min = 3.5, max = 5;
  const weekLabels = ['4 semanas', '3 semanas', '2 semanas', '1 semana', '0–6 días'];
  const point = (item, index) => item.n >= 10 && item.rating !== null ? `${pad + index * ((width - pad * 2) / 4)},${pad + (max - item.rating) * ((height - pad * 2) / (max - min))}` : null;
  const points = metric.weekly.map(point);
  const segments = []; let active = [];
  points.forEach((value, index) => { if (value) active.push(value); else { if (active.length > 1) segments.push(active.join(' ')); active = []; } if (index === points.length - 1 && active.length > 1) segments.push(active.join(' ')); });
  const dots = metric.weekly.map((item, index) => { const value = point(item, index); return value ? `<circle cx="${value.split(',')[0]}" cy="${value.split(',')[1]}" r="2.5"/>` : ''; }).join('');
  const tooltips = metric.weekly.map((item, index) => { const x = pad + index * ((width - pad * 2) / 4); const rating = item.rating === null ? 'sin reseñas' : item.rating.toFixed(2).replace('.', ','); const gap = item.n < 10 ? ' · sin punto: n < 10' : ''; return `<rect class="spark-hit" x="${x-10}" y="0" width="20" height="${height}"><title>${weekLabels[index]} · ${item.n} reseñas · nota ${rating}${gap}</title></rect>`; }).join('');
  const baseline = metric.baseline === null ? '' : `<line class="spark-base" x1="${pad}" x2="${width-pad}" y1="${pad + (max - metric.baseline) * ((height - pad * 2) / (max - min))}" y2="${pad + (max - metric.baseline) * ((height - pad * 2) / (max - min))}"><title>Antes del último mes · ${metric.baseline.toFixed(2).replace('.', ',')}</title></line>`;
  return `<svg class="sparkline" viewBox="0 0 ${width} ${height}" role="img" aria-label="Evolución semanal de 4 semanas a los últimos 6 días; eje de 3,5 a 5,0">${baseline}${segments.map(segment=>`<polyline points="${segment}"/>`).join('')}${dots}${tooltips}</svg>`;
}
