function escapeHtml(value){return String(value||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function dayTopic(text){const normalized=text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const found=Object.entries(dayTopics).filter(([,words])=>words.some(word=>normalized.includes(word))).map(([name])=>name);return found.length?found.join(', '):'sin clasificar';}
