function renderDayTimeline(){const target=document.getElementById('timeline');if(!target)return;const stats=dayStats(selectedDayVenue), maxNegative=Math.max(...stats.map(item=>item.negative),1);target.innerHTML=stats.map((item,index)=>{const noData=item.n===0;const count=noData?'sin datos':`${item.negative} ${item.negative===1?'negativa':'negativas'} de ${item.n} ${item.n===1?'reseña':'reseñas'}`;const bar=noData?'':`<i><b style="height:${item.negative/maxNegative*100}%"></b></i>`;const rating=noData?'':`<small>${item.rating.toFixed(2).replace('.',',')}★</small>`;return `<button class="timeline-item${selectedDayLabel===item.label?' selected':''}${index===4?' day-separator':''}${noData?' no-data':''}" data-day-label="${item.label}" role="listitem" title="${formatDayLabel(item.label)}"><strong>${count}</strong>${bar}${rating}<label>${formatDayLabel(item.label,true)}</label></button>`;}).join('');}
function renderDayReview(review, showVenue){const venueName=id=>venues.find(v=>v.id===id)?.name||id;return `<div class="evidence-item"><strong>${showVenue?escapeHtml(venueName(review.venue))+' · ':''}<span class="star-rating">${'★'.repeat(review.rating)}${'☆'.repeat(5-review.rating)}</span></strong><p><b>Tema:</b> ${escapeHtml(dayTopic(review.text))}</p><p>${review.text?escapeHtml(review.text):'Esta reseña no trae texto.'}</p><a href="${escapeHtml(review.url)}" target="_blank" rel="noreferrer">Abrir reseña original en Google ↗</a></div>`;}
function renderDayDetail(){const target=document.getElementById('day-detail');if(!target)return;const stats=dayStats(selectedDayVenue), venueLabel=selectedDayVenue?(venues.find(v=>v.id===selectedDayVenue)?.name||selectedDayVenue):'Grupo completo', reviewsFor=item=>timelineData.group.find(x=>x.label===item.label).reviews.filter(review=>selectedDayVenue===null||review.venue===selectedDayVenue);if(selectedDayLabel===null){const content=stats.map(item=>{const reviews=reviewsFor(item);const message=item.n===0?'No hay reseñas en este tramo.':reviews.length?'':`Este tramo no tiene negativas. Sí tuvo ${item.n} ${item.n===1?'reseña':'reseñas'}.`;return `<section class="day-detail-group"><h3>${formatDayLabel(item.label)}</h3>${reviews.map(review=>renderDayReview(review,selectedDayVenue===null)).join('')}${message?`<p class="insight-note">${message}</p>`:''}</section>`;}).join('');target.innerHTML=`<div class="card-heading"><div><p class="eyebrow">${venueLabel}</p><h3>Negativas de todos los tramos</h3></div></div>${content}<p class="insight-note">Los temas se detectan por palabras clave y no interpretan el sentido de la frase. Confirma siempre en la reseña original.</p>`;return;}const item=stats.find(x=>x.label===selectedDayLabel),reviews=reviewsFor(item),heading=item.n===0?'Sin datos':`${item.negative} ${item.negative===1?'negativa':'negativas'} en ${item.n} ${item.n===1?'reseña':'reseñas'}`,content=item.n===0?'<p class="insight-note">No hay reseñas en este tramo.</p>':reviews.length?reviews.map(review=>renderDayReview(review,selectedDayVenue===null)).join(''):`<p class="insight-note">Este tramo no tiene negativas. Sí tuvo ${item.n} ${item.n===1?'reseña':'reseñas'}.</p>`;target.innerHTML=`<div class="card-heading"><div><p class="eyebrow">${venueLabel} · ${formatDayLabel(item.label)}</p><h3>${heading}</h3></div></div>${content}<p class="insight-note">Los temas se detectan por palabras clave y no interpretan el sentido de la frase. Confirma siempre en la reseña original.</p>`;}
