const askDialog=document.getElementById('ask-dialog'); document.getElementById('open-ask').addEventListener('click',()=>askDialog.showModal()); document.getElementById('close-ask').addEventListener('click',()=>askDialog.close()); document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>showAnswer(b.dataset.question))); document.getElementById('ask-form').addEventListener('submit',e=>{e.preventDefault();const q=document.getElementById('ask-input').value.toLowerCase(), venue=criticalVenue();showAnswer(venue&&q.includes(venue.name.toLowerCase())?'critical':q.includes('mezcl')||q.includes('tripadvisor')?'method':'priority');});
function pct(n, total){ return total ? n/total*100 : 0; }
function pctLabel(n, total){ return total ? (n/total*100).toFixed(total<50?1:0).replace('.',',')+' %' : '—'; }
// El numero absoluto va a la IZQUIERDA de la barra: dentro no se leia sobre el color.
function doubleBarRow(label, aValue, aTotal, bValue, bTotal){
  const bar=(cls,v,t)=>`<b class="dbr-n">${v}</b><i class="${cls}" style="width:${pct(v,t)}%"></i><span class="dbr-pct">${pctLabel(v,t)}</span>`;
  return `<div class="double-bar-row"><span class="dbr-label">${label}</span>`
    + `<div class="double-bars">${bar('series-rest',aValue,aTotal)}${bar('series-recent',bValue,bTotal)}</div></div>`;
}
// Los dos graficos comparan LA MISMA ventana: ultimas 100 frente al resto de la muestra.
// La ventana de 25 se queda en la tabla: con 25 resenas solo hay una o dos negativas,
// que no dan para hablar de temas.
function renderReviewInsights(analysis, sample, restBad, recentBad) {
  const stars=analysis.stars;
  const rest=stars.rest||[0,0,0,0,0];
  const totalRecent=stars.recent_sample.reduce((a,b)=>a+b,0), totalRest=rest.reduce((a,b)=>a+b,0);
  const starRows=stars.recent_sample.map((count,i)=>
    doubleBarRow(`${i+1}★`, rest[i], totalRest, count, totalRecent)).join('');
  // Solo se oculta si no hay nada que repartir: sin negativas recientes, o con todas
  // sin palabra clave reconocible. Un grafico de ceros parece un fallo del panel.
  const temasTotal=Object.values(analysis.topics).reduce((a,c)=>a+c.recent+c.rest,0);
  const insufficient=!recentBad||!temasTotal;
  const muestraCorta=recentBad&&recentBad<10;
  const themeRows=Object.entries(analysis.topics).map(([name,c])=>{
    const rises=c.recent/recentBad>c.rest/restBad;
    return doubleBarRow(name+(rises?' ↑':''), c.rest, restBad, c.recent, recentBad);
  }).join('');
  const legend=(a,b)=>`<div class="double-bar-legend"><span><i class="series-rest"></i>${a}</span><span><i class="series-recent"></i>${b}</span></div>`;
  // Kioto solo tiene 60 reseñas: la etiqueta dice el tamaño real de cada ventana, no '100'.
  const etiquetaReciente=`últimas ${numberFormatter.format(totalRecent)}`;
  const etiquetaResto=totalRest?`resto de la muestra (${numberFormatter.format(totalRest)} reseñas)`:'resto de la muestra: no hay';
  return `<section class="detail-section"><h3>Distribución de estrellas</h3>`
    + legend(etiquetaResto, etiquetaReciente)
    + `<div class="double-bar-chart pct-chart">${starRows}</div>`
    + `<p class="insight-note">A la izquierda de cada barra, cuántas reseñas. A la derecha, qué porcentaje representan sobre su propia ventana, que es lo que permite comparar dos muestras de tamaño distinto.</p>`
    + `</section>`
    + `<section class="detail-section"><h3>Qué está fallando</h3>`
    + (insufficient
      ? `<p class="insight-note">Sin temas que mostrar: ${!recentBad?'no hay reseñas negativas en la ventana reciente':recentBad===1?'la única negativa reciente no contiene ninguna palabra clave reconocible':`las ${recentBad} negativas recientes no contienen ninguna palabra clave reconocible`}.</p>`
      : legend(totalRest?`resto de la muestra (${restBad} negativas)`:'resto de la muestra: no hay', `${etiquetaReciente} (${recentBad} negativas)`)
        + `<div class="double-bar-chart pct-chart">${themeRows}</div>`
        + (muestraCorta?`<p class="insight-note">Muestra corta: solo ${recentBad} ${recentBad===1?'negativa reciente':'negativas recientes'}. Sirve para ver dónde se concentran, no para concluir una tendencia.</p>`:'')
        + `<p class="insight-note">Mismas dos ventanas que el gráfico anterior, pero contando solo las reseñas de 1 y 2 estrellas. La flecha marca los temas que ganan peso.</p>`
        + `<p class="insight-note">Sin clasificar: ${analysis.unclassified.rest} de ${restBad} → ${analysis.unclassified.recent} de ${recentBad}</p>`
        + `<p class="insight-note">Los temas se detectan por palabras clave sobre el texto de las reseñas negativas, sin interpretar el sentido de cada frase. Alrededor de una de cada diez incluye además algún elogio, así que estas cifras sirven para orientar dónde mirar, no para contar quejas. Confirma siempre en las reseñas originales.</p>`)
    + `</section>`;
}
const initialView=location.hash.slice(1); if(viewTitles[initialView])setView(initialView);
// sin esto la URL y la vista se desincronizan al pulsar el logo o al usar atras/adelante
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1); if(viewTitles[v])setView(v);});
